    /**
     * Maximum message date to return
     *
     * @default  `0` (disabled).
     */
    maxDate?: number | Date;
    /**
     * Thread ID to return only messages from this thread.
     */
    threadId?: number;
    /**
     * Limits the number of messages to be retrieved.
     *
     * @default  100
     */
    limit?: number;
